import { Editor as TinymceEditor } from '@tinymce/tinymce-react';
import {
    Backdrop,
    Box, CircularProgress
} from '@mui/material';
import init from '../config/init';
import { useEffect, useRef, useState } from 'react';

export default function Editor (props) {
    const [values, setValues] = useState({
        loading: true,
        text:'',
    })
    const content = useRef();
    useEffect(() => {
        console.log(content?.current.editor.contentDocument);
    })
    return (
        <Box>
            <TinymceEditor
                //tinymceScriptSrc={`${process.env.PUBLIC_URL}/scripts/tinymce.min.js`}
                init={{
                    ...init,
                    language: 'fr_FR',
                }}
                //initialValue=".........."
                scriptLoading={{ async: true }}
                onLoadContent={() => setValues({...values, loading: false})}
                apiKey="33ba4vme0xl5wrumyggywiormvv4uhvixrmcoxhv38hg4g2b"
                ref={content}
                value={values.text}
                onEditorChange={text => setValues({...values, text})}
            />
            <Backdrop
                sx={{
                color: '#fff',
                zIndex: (theme) => theme.zIndex.drawer + 1,
                backdropFilter: 'blur(15px)',
                }}
                open={values.loading}
            >
                <CircularProgress
                    color="inherit"
                    size="small"
                    sx={{
                        width: 25,
                        height: 25
                    }}
                />
            </Backdrop>
        </Box>
    );
}

