import { useSelector } from "react-redux"
import {
    Grid,
    Stack,
    Box,
    Typography,
} from '@mui/material';
import fileExtensionBase from "../../../../../utils/fileExtensionBase";
import getFileExtension from "../../../../../utils/getFileExtension";
import StackPaper from '../../../../../components/StackPaper';
import handleLocalDateStr from "../../../../../utils/handleLocalDateStr";

export default function ArchivesDocsContent () {
    const data = useSelector(state => {
        const data = state.archivesNavRight.value?.data;
        return Array.isArray(data) && data?.filter(({contentUrl}) => fileExtensionBase?.find(({exts}) => 
            ~exts.indexOf(getFileExtension(contentUrl)))?.type === 'document'
        );
    });
    const open = useSelector(state => state.archivesNavLeft.value.open);

    return (
        <Box
            display="flex"
            flex={1}
            sx={{m:1}}
        >
          { data?.length > 0 &&
            <Grid container spacing={1}>
                {data.map((doc, index) => 
                     (<Grid  item key={index} xs={1} md={6} lg={ open ? 4 : 3}>
                        <Box>
                            <StackPaper
                                coverUrl={doc.coverUrl}
                                title={doc.designation}
                                date={handleLocalDateStr(doc.createdAt)}
                                link={doc.contentUrl}
                                description={doc.description}
                            />
                        </Box>
                     </Grid>)
                )}
               
            </Grid>
         }
         {data?.length === 0 &&
             <Stack
                display="flex"
                flex={1}
                justifyContent="center"
                alignItems="cenetr"
             >
                <Typography align="center" variant="caption" color="text.secondary">
                    Aucun élement trouvé
                </Typography>
             </Stack>
         }
        </Box>
    )
}