import {
    AppBar,
    Toolbar,
    IconButton,
    Typography,
    useTheme,
    Tooltip,
    Badge,
    Box,
} from '@mui/material';
import Menu from '@mui/icons-material/Menu';
import { useContext } from 'react';
import { TextEditorProps } from '../TextEditor';
import MenuOpenRoundedIcon from '@mui/icons-material/MenuOpenRounded';
import { useNavigate } from 'react-router-dom';
import ExitToAppRoundedIcon from '@mui/icons-material/ExitToAppRounded';
import SaveRoundedIcon from '@mui/icons-material/SaveRounded';
import FormInputTheme from '../../../config/FormInputTheme';
import SettingsRoundedIcon from '@mui/icons-material/SettingsRounded';
import { useConfig } from '../../../services/globalConfig';

export default function TextEditorHeader (props) {
    const [context, handleChange] = useContext(TextEditorProps);
    const theme = useTheme();
    const [, actions] = useConfig();
    const navigateTo = useNavigate();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    return (
        <FormInputTheme>
            <AppBar 
                position="sticky" 
                sx={{
                    bgcolor: theme => theme.palette.background.paper + 'ee',
                    backdropFilter: 'blur(15px)',
                }}
            >
            <Toolbar>
                {!context.openNavLeft &&
                <IconButton
                    size="small"
                    edge="start"
                    onClick={handleChange('openNavLeft', !context.openNavLeft)}
                >
                    <MenuOpenRoundedIcon />
                </IconButton>}
                <Typography variant="h6" color={color} sx={{mx:1, flexGrow: 1}}>
                    Editeur de documents
                </Typography>
                <Box>
                    <Tooltip arrow title="sauvegarder" enterDelay={700}>
                        <IconButton
                            size="small"
                            onClick={() => {
                                //navigateTo('/home');
                            }}
                        >
                            <Badge color="primary" variant="dot">
                                <SaveRoundedIcon fontSize="small"/>
                            </Badge>
                        </IconButton>
                        
                    </Tooltip>
                </Box>
                <Box>
                    <Tooltip arrow title="Paramètre" enterDelay={700}>
                        <IconButton size="small"
                            onClick={() => actions(null).handleChangeProps({settingsNav: true})}
                        >
                            <SettingsRoundedIcon fontSize="small"/>
                        </IconButton>
                    </Tooltip>
                </Box>
                <Box>
                    <Tooltip arrow title="sortir" enterDelay={700}>
                        <IconButton
                            size="small"
                            onClick={() => {
                                navigateTo('/home');
                            }}
                        >
                            <ExitToAppRoundedIcon fontSize="small"/>
                        </IconButton>
                    </Tooltip>
                </Box>
            </Toolbar>
            </AppBar>
        </FormInputTheme>
    );
}