import * as React from "react";
import { 
    List, 
    ListItem, 
    ListItemButton, 
    ListItemText, 
    ListItemIcon,
    ListSubheader,
    Stack,
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import ImgToIcon from '../../../../../icons/ImgToIcon';
import { setTab } from "../../../../../redux/apps/archives/archivesNavRight";
import useSize from "../../../../../services/useSize";
import { closeNav } from "../../../../../redux/apps/archives/archivesNavLeft";
import options from "./options";


export default function Category () {
    const selectedTab = useSelector(state => state.archivesNavRight.value.tab);
    const dispatch = useDispatch();
    const size = useSize();
    const isSmallScreen = !!['xs', 'md'].find(key => size.key === key);


    return (
        <Stack
            display="flex"
        >
            <List
                sx={{
                    width: '100%',
                    position: 'relative',
                    overflow: 'auto',
                    mt: 1,
                }}
                disablePadding
                subheader={
                    <ListSubheader component="div">
                        Catégorie
                    </ListSubheader>
                }
            >
            {options.map((tab, index) => (
                <ListItem 
                    key={`${index}`} 
                    sx={{m:0, p: 0, fontSize: 15}}
                    selected={tab.id === selectedTab}
                    disabled={tab.disabled}
                    button
                    onClick={() => {
                        dispatch(setTab(tab.id));
                        if(isSmallScreen)
                            dispatch(closeNav());
                    }}
                    
                >
                    <ListItemButton>
                        <ListItemIcon>
                            <ImgToIcon
                                src={tab.icon}
                                size={30}
                            />
                        </ListItemIcon>
                        <ListItemText 
                            primary={`${tab.label}`} 
                            primaryTypographyProps={{
                                color:'text.primary'
                            }}
                        />
                    </ListItemButton>
                </ListItem>
                ))
                }
            </List>
            
        </Stack>
    );
}