import { 
    Alert,
    AlertTitle,
    Box, 
    Divider, 
    Fade, 
    LinearProgress, 
    Stack, 
    Toolbar, 
    Typography,
} from '@mui/material';
import useAxios from 'axios-hooks';
import propTypes from 'prop-types';
import * as React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import GeidLogo from '../../../components/GeidLogo';
import archiveIconImage from '../../../icons/icons8-file-64.png';
import ImgToIcon from '../../../icons/ImgToIcon';
import { openApp, setData, setLoad } from '../../../redux/apps/archives/archivesNavRight';
import serverPath from '../../../services/serverPath';

export const useGetData = (load) => {
    const { id: userId, level, token} = useSelector(state => state.user.value);
    const localData = useSelector(state => state.archivesNavRight.value.data);
    const role = useSelector(state => state.archivesNavRight.value.role) || level.role;
    const type = useSelector(state => state.archivesNavRight.value.type);
    const archivesURL = URL_ARCHIVES + JSON.stringify({ userId, role, type});
    const [{data, error, loading}, refrech, ] = useAxios({   
            url:archivesURL,
            headers: { 'Authorization': `Bearer ${token}`, },  
        }, {
            manual: true
    });
    const dispacth = useDispatch();
    
    React.useEffect(() => {
        let timer = null;
        
        if(load) {
            timer = localData ? null : window.setTimeout(() => {
                refrech();
            },2000);

            if(data) {
                if(JSON.stringify(localData) !== JSON.stringify(data)) 
                    dispacth(setData(data));
            } else {
                if(!timer) 
                    refrech(archivesURL);
            }
        }
        return () => { 
            if(timer)
                window.clearTimeout(timer);
        }
    }, [data, localData, refrech, dispacth, load, role, type]);

    React.useEffect(() => {
        dispacth(setLoad(loading));
    }, [loading, setLoad, dispacth]);

    return [{loading, error}, refrech];
};

export default function ArchivesCover ({loadData}) {
    const data = useSelector(state => state.archivesNavRight.value.data);
    const tab = useSelector(state => state.archivesNavRight.value.tab);
    const dispacth = useDispatch();
    const [{loading, error: errorGetArchives}, getArchives] = useGetData(loadData);
    const [error, setError] = React.useState(null);
    const open = !data;

    React.useEffect(() => {
        if(loadData && (tab !== 'home')) 
            if(typeof getArchives === 'function') 
                getArchives();
        if(!open) 
            dispacth(openApp());
    }, [tab, open, loadData, dispacth, getArchives]);

    /*Handle the all errors */
    React.useEffect(() => {
        
        if(errorGetArchives && !error) 
            if((errorGetArchives.code === 'ERR_NETWORK') && !errorGetArchives.response?.data)
                setError({
                    title: 'Promblème de réseau',
                    message: `Impossible d'acceder aux archives, 
                    votre apareil n'est pas connecté sur internet`
                });

    }, [error, errorGetArchives, setError]);
    
    // React.useEffect(() => {
    //     if(getBookTypes) 
    //             dispacth(setBookTypes({bookTypes: getBookTypes}));
    // }, [getBookTypes]);

    if(open)
        return (
            <Box
                sx={{ 
                    zIndex: (theme) => theme.zIndex.drawer + 1,
                    bgcolor: 'background.paper',
                    hight: '100vh',
                    width: '100vw',
                    position: 'fixed',
                    display: 'flex',
                    flex: 1,
                    justifyContent: 'center',
                    alignItems: 'center',
                    top: 0,
                    left: 0,
                    bottom: 0,
                    right: 0
                }}
            >
                <Stack spacing={1}>
                    <Toolbar
                        sx={{
                            justifyContent: 'center',
                            alignItems: 'center',
                            display: 'flex',
                            //bgcolor: 'red',
                        }}
                    >
                        <Box>
                            <ImgToIcon
                                src={archiveIconImage}
                                size={50}
                            />
                        </Box>
                        <Divider orientation="vertical" variant="middle" flexItem />
                        <Typography color="text.primary" sx={{mx: 1}} variant="h6">Archives</Typography>
                    </Toolbar>
                    <Box sx={{px:3, color: 'text.primary'}}>
                        <Fade in={loadData}>
                            {!!error ?
                        ( <Alert
                                severity='error'
                                children={
                                    <React.Fragment>
                                        <AlertTitle>{error.title}</AlertTitle>
                                        {error.message}
                                    </React.Fragment>
                                }
                            />) :
                            (<LinearProgress
                                color="inherit"
                            />)}
                        </Fade>
                    </Box>
                </Stack>

                <Stack 
                    position="absolute"
                    bottom={80}
                >
                    <Typography 
                        variant="body2" 
                        color="text.secondary"
                        align="center"
                        component="div"
                    >
                        <GeidLogo 
                            sx={{ color: 'text.primary' }}
                            
                        />
                    </Typography>
                    <Typography 
                        variant="body2" 
                        color="text.secondary"
                        component="div"
                    >
                        Direction Archives et Nouvelles Technologie de l'Information et de la Communication
                    </Typography>
                    
                </Stack>
            </Box>
        );
}

ArchivesCover.defaultProps = {
    loadData: false,
};
   

ArchivesCover.propTypes = {
    loadData: propTypes.bool,
};

const URL_ARCHIVES = serverPath('api/stuff/archives/');