import { 
    Divider, 
    Slide, 
    Stack,
} from "@mui/material";
import ArchivesNavLeft from "./navleft/ArchivesNavLeft";
import ArchivesNavRight from "./navright/ArchivesNavRight";

import { SnackbarProvider } from "notistack";
import ArchivesCover from "./cover/ArchivesCover";
import { useSelector } from "react-redux";
import React from "react";
import StackPaper from "../../components/StackPaper";

export default function Archives () {
    const open = !!useSelector(state => state.archivesNavRight.value.open);
    
    return ( 
        <React.Fragment>
           { open &&
            <SnackbarProvider maxSnack={1}>
                <Slide in={open} direction="up">
                    <Stack 
                        height="100vh"
                        display="flex"
                        direction="row"
                        overflow="hidden"
                        divider={<Divider orientation="vertical" flexItem/>}
                        flex={1}
                    >
                        <ArchivesNavLeft/>
                        <ArchivesNavRight/>
                    </Stack>
                </Slide> 
            </SnackbarProvider>}
            <ArchivesCover loadData={true}/>
        </React.Fragment>
    )
}