import { 
    Stack, Button, Divider,

} from "@mui/material";
import { Box } from "@mui/system";
import { useDispatch, useSelector } from "react-redux";
import GroupButtonTab from "../../../../../components/GroupButtonTab";
import { tabsClasses } from '@mui/material/Tabs';
import FormInputTheme from '../../../../../config/FormInputTheme';
import { setType } from "../../../../../redux/apps/archives/archivesNavRight";

export default function ArchivesHeaderContent () {
    const defaultDocType = useSelector(state => state.user.value.docTypes);
    const docTypes = useSelector(state => state.archivesNavRight.value.docTypes) || defaultDocType || [];
    const options = [
        {label: 'TOUS', value: null},
        ...docTypes?.map(({subtypes, name:label}, index) => ({
        label,
        ...subtypes?.length > 0 ? {
            subOptions: subtypes.map((label, subIndex) => ({
                label,
            })),
            
        } :{}
    }))];
   
    const dispatch = useDispatch();
    const handleChange = (event, {label}) => {
        dispatch(setType(label === 'TOUS' ? null : label));
    }

    const defaultIndex = undefined

    return (
        <Box
            sx={{
                m:1, 
                mt: 0,
                bgcolor: 'background.paper',
                top: 0,
                position: 'sticky',
                //zIndex: theme => theme.zIndex.appBar - 1,
                display: 'flex',
                overflow: 'hidden',
            }}
        >
          <Stack 
            mt={1}
            overflow="hidden"
            flex={1}
          >
            <FormInputTheme>
                <GroupButtonTab
                    options={options}
                    indicator={false}
                    onChange={handleChange}
                    defaultIndex={defaultIndex}
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        [`& .${tabsClasses.scrollButtons}`]: {
                            '&.Mui-disabled': { opacity: 0.3 },
                            color: 'text.primary',
                        },
                    }}
                />
            </FormInputTheme>
          </Stack>
          <Divider/>
        </Box>
    )
}